import{_ as e,o,c as i,a5 as a}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"Low Level (RL Policy) — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/low-level.md","filePath":"software/sdk/python/low-level.md","lastUpdated":1787021357000}'),s={name:"software/sdk/python/low-level.md"};function d(n,t,r,l,h,c){return o(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="low-level-rl-policy-—-python-example" tabindex="-1">Low Level (RL Policy) — Python Example <a class="header-anchor" href="#low-level-rl-policy-—-python-example" aria-label="Permalink to &quot;Low Level (RL Policy) — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_low_level.py</code></p><p>Python port of <a href="/RBQ/nightly/software/sdk/cpp/low-level.html"><code>rbq_low_level.cpp</code></a>.<br> Subscribes to IMU, joystick, and leg-joint feedback topics, publishes joint position references, and runs a <strong>learned walking policy (ONNX)</strong> at 100 Hz.</p><h2 id="behavior-overview" tabindex="-1">Behavior overview <a class="header-anchor" href="#behavior-overview" aria-label="Permalink to &quot;Behavior overview&quot;">​</a></h2><p>A single <strong>500 Hz control loop</strong> (2 ms period) runs in a background thread. A keyboard-driven state machine controls which mode is active:</p><table tabindex="0"><thead><tr><th>State</th><th>Key</th><th>What the control loop does</th></tr></thead><tbody><tr><td><strong>Idle</strong></td><td>—</td><td>Tracks <code>rt/rbq/ref/motion/_0</code> and republishes it as a pass-through</td></tr><tr><td><strong>Motion</strong></td><td><code>x</code> / <code>z</code></td><td>Cosine-interpolates joints to <code>ready</code> or <code>ground</code> postures</td></tr><tr><td><strong>Control</strong></td><td><code>c</code></td><td>Loads the ONNX policy, runs inference at <strong>100 Hz</strong> (every 5th tick), publishes <code>MotionRef_</code></td></tr></tbody></table><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> installed — see <a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li><strong>onnxruntime</strong>: <code>pip install onnxruntime</code></li><li>A policy directory containing <code>info.json</code> and <code>policy.onnx</code>.</li><li>Robot stack running (simulation or hardware).</li></ul><h2 id="install-run" tabindex="-1">Install &amp; Run <a class="header-anchor" href="#install-run" aria-label="Permalink to &quot;Install &amp; Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> onnxruntime</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># networkInterface is optional (defaults to loopback for simulation)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_low_level.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">policyDi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e.g.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_low_level.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../../../rbq_simulator/rbq_gym/policy/rbq10/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_low_level.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../../../rbq_simulator/rbq_gym/policy/rbq10/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><blockquote><p>Unlike the C++ version, <strong><code>sudo</code> is not required</strong> — Python does not use a real-time thread.</p></blockquote><h2 id="run-with-simulation" tabindex="-1">Run with simulation <a class="header-anchor" href="#run-with-simulation" aria-label="Permalink to &quot;Run with simulation&quot;">​</a></h2><ol><li>From <code>RBQ/</code>, start the simulator:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div></li><li>In RBQGUI: <strong>Connect</strong> → <strong>Auto Start Robot</strong> → <strong>Stance</strong> (key <code>2</code>).</li><li>Run the example (loopback — no interface needed for sim):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_low_level.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../../../rbq_simulator/rbq_gym/policy/rbq10/</span></span></code></pre></div></li></ol><h2 id="keyboard-controls" tabindex="-1">Keyboard controls <a class="header-anchor" href="#keyboard-controls" aria-label="Permalink to &quot;Keyboard controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>q</code></td><td>Quit</td></tr><tr><td><code>z</code></td><td>Go to <strong>ground</strong> posture (folding → ground, ~4.8 s)</td></tr><tr><td><code>x</code></td><td>Go to <strong>ready</strong> posture (ground → folding → ready, ~2.8–5.6 s)</td></tr><tr><td><code>c</code></td><td>Start <strong>Walk / Control</strong> mode (loads policy from <code>-p</code>)</td></tr></tbody></table><p>Keyboard is read in non-canonical, no-echo mode — no Enter required.</p><h2 id="policy-directory" tabindex="-1">Policy directory <a class="header-anchor" href="#policy-directory" aria-label="Permalink to &quot;Policy directory&quot;">​</a></h2><p>The <code>-p</code> directory must contain:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.json</code></td><td>Policy hyper-parameters (<code>run_name</code>, <code>policy_dt</code>, <code>action_scale</code>, stiffness/damping, obs/action sizes, normalization scales, default joint angles, command ranges)</td></tr><tr><td><code>policy.onnx</code></td><td>ONNX model exported from the training framework</td></tr></tbody></table><p>Supported policy names (from <code>info.json</code> <code>run_name</code>):</p><table tabindex="0"><thead><tr><th>Name</th><th>Observation vector</th><th>Notes</th></tr></thead><tbody><tr><td><code>rbq10</code></td><td>gyro, proj_grav, command, dof_pos, dof_vel, action</td><td>Single-frame</td></tr><tr><td><code>rbq10_trot</code></td><td>gyro, proj_grav, command, 4×dof_pos history (0,2,4,6), 4×dof_vel history, action×2, added_mass</td><td>7-frame history</td></tr><tr><td><code>rbq10_trot_run</code></td><td>Same as <code>rbq10_trot</code></td><td>Faster run variant</td></tr></tbody></table><h2 id="dds-topics" tabindex="-1">DDS topics <a class="header-anchor" href="#dds-topics" aria-label="Permalink to &quot;DDS topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Topic</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Subscribe</td><td><code>rt/rbq/joy</code></td><td><code>Joy_</code></td><td>Joystick axes for velocity commands</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/imu</code></td><td><code>Imu_</code></td><td>Angular velocity + orientation quaternion</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/leg_joint</code></td><td><code>LegJointInfo_</code></td><td>Joint position and velocity (12 joints)</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/ref/motion/_0</code></td><td><code>MotionRef_</code></td><td>Final blended reference (used in Idle)</td></tr><tr><td>Publish</td><td><code>rt/rbq/ref/motion/_20</code></td><td><code>MotionRef_</code></td><td>Joint position references with PD gains</td></tr><tr><td>Publish</td><td><code>rt/rbq/cmd/motion/owner/_20</code></td><td><code>JointOwnershipCmd_</code></td><td>Claim ownership of all 12 joints</td></tr></tbody></table><h2 id="joint-ordering" tabindex="-1">Joint ordering <a class="header-anchor" href="#joint-ordering" aria-label="Permalink to &quot;Joint ordering&quot;">​</a></h2><p>Joints indexed 0–11:</p><p><code>HR</code>: <code>HRR(0)</code>, <code>HRP(1)</code>, <code>HRK(2)</code> → <code>HL</code>: <code>HLR(3)</code>, <code>HLP(4)</code>, <code>HLK(5)</code> → <code>FR</code>: <code>FRR(6)</code>, <code>FRP(7)</code>, <code>FRK(8)</code> → <code>FL</code>: <code>FLR(9)</code>, <code>FLP(10)</code>, <code>FLK(11)</code></p><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong>No RT thread</strong>: Python&#39;s <code>time.sleep()</code> is used for 2 ms pacing. Timing jitter is higher than the C++ RT thread — acceptable for simulation and testing, but less suitable for highly dynamic real-robot use.</li><li><strong>Observation pre-initialization</strong>: <code>msg_imu</code>, <code>msg_leg</code>, and <code>msg_joy</code> are pre-initialized with zero defaults in <code>SharedState</code>. The policy runs immediately on launch even before the first DDS sample arrives; a throttled warning is printed if any subscriber is still cold.</li><li><strong>Decimation</strong>: Policy inference runs every 5th loop tick (100 Hz from the 500 Hz loop), matching <code>policy_dt</code> in <code>info.json</code>.</li><li><strong>Ownership</strong>: <code>JointOwnershipCmd_</code> is published once on entering Motion or Control state, claiming all 12 joints at priority 20.</li><li><strong>Posture detection</strong>: <code>go_to_motion_ready()</code> checks the four hip-pitch angles against 60° to determine if the robot is grounded, inserting a folding step if needed.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th></tr></thead><tbody><tr><td>No motion / topics silent</td><td>Stack not running or wrong network interface</td></tr><tr><td><code>Policy, PolicyParams not loaded</code></td><td><code>-p</code> path wrong, or <code>info.json</code> / <code>policy.onnx</code> missing</td></tr><tr><td><code>NaN or Inf in output data</code></td><td>Policy received invalid observation; check IMU and joint topics</td></tr><tr><td>Timing warnings in log</td><td>System too loaded for 2 ms; close other processes</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/cpp/low-level.html">Low Level (RL Policy) (C++)</a></li><li><a href="/RBQ/nightly/software/sdk/python/high-level.html">High Level Command (Python)</a></li><li><a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a></li><li><a href="/RBQ/nightly/software/simulator/rbq-gym.html">Isaac Gym</a></li><li><a href="/RBQ/nightly/software/simulator/rbq-lab.html">Isaac Lab</a></li></ul>`,33)])])}const y=e(s,[["render",d]]);export{g as __pageData,y as default};
